FRAMES = {
    "desk-board": lambda look, cards, opened: f"{LOOK}\n\n{DARK}\n\n{DESK}\n\n{CARDS}\n\n{look}\n\n{TAIL}",
    "desk-open": lambda look, cards, opened: f"{LOOK}\n\n{DARK}\n\n{DESK}\n\n{DESK_OPEN}\n\n{OPENED}\n\n{opened}\n\n{TAIL}",
    "phone-board": lambda look, cards, opened: f"{LOOK}\n\n{LIGHT}\n\n{PHONE_BOARD}\n\n{CARDS}\n\n{look}\n\n{TAIL}",
    "phone-open": lambda look, cards, opened: f"{LOOK}\n\n{LIGHT}\n\n{PHONE_OPEN}\n\n{OPENED}\n\n{opened}\n\n{TAIL}",
}

for key, (name, cards, opened) in D.items():
    bare = "" if key == "D" else '\nNo label such as "Why:", "Place:" or "Plan:" stands before any line.'
    look = f'Direction {key}, "{name}", for the cards:\n{cards}{bare}'
    op = f'Direction {key}, "{name}", for the opened card:\n{opened}{bare}'
    for frame, make in FRAMES.items():
        (R / f"{key}-{frame}.txt").write_text(make(look, cards, op) + "\n")
print(len(D) * len(FRAMES), "prompts")
